 let points=new Map(),model,time=45000,selected='foundation.lead',visible=new Set(ids),trace=false,layout='orbital',zoom=1,pan={x:0,y:0},motion=false,hover=null;
function posLayout(w,h){points=new Map();const cx=w/2,cy=h/2;const gapX=w*.28,gapY=h*.27;const rad=Math.min(w*.205,h*.215);for(let ti=0;ti<4;ti++){const t=teams[ti],x=cx+(ti%2?gapX:-gapX),y=cy+(ti>1?gapY:-gapY),list=ids.filter(a=>a.startsWith(t.id+'.'));for(let j=0;j<list.length;j++){let px=x,py=y;if(j>0){if(layout==='grid'){const k=j-1;px=x+((k%8)-3.5)*rad*.235;py=y+(Math.floor(k/8)+.8)*rad*.24-rad*.35;}else{const ring=j<=10?1:2,k=ring===1?j-1:j-11,count=ring===1?10:21,ang=2*Math.PI*k/count- Math.PI/2+ti*.25;const rr=rad*(ring===1?.52:.91);px=x+Math.cos(ang)*rr;py=y+Math.sin(ang)*rr;}}points.set(list[j],{x:px,y:py,team:t.id,lead:j===0});}}}
function resize(){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);if(canvas.width!==Math.round(r.width*d)||canvas.height!==Math.round(r.height*d)){canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d);}ctx.setTransform(d,0,0,d,0,0);posLayout(r.width,r.height);return {w:r.width,h:r.height};}
function col(hex,a){return `rgba(${parseInt(hex.slice(1,3),16)},${parseInt(hex.slice(3,5),16)},${parseInt(hex.slice(5,7),16)},${a})`}
