// Restrained radar rings and supervisory topology. These are explicitly structural, not traffic.
ctx.strokeStyle='#244e60';ctx.setLineDash([2,7]);for(let r=35;r<Math.min(w,h)*.53;r+=48){ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.stroke()}ctx.setLineDash([]);
